// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Bound value to avoid overflow/underflow issues
        value = bound(value, 0, address(c).balance);

        // Ensure the caller is the owner (which is the deployer)
        vm.prank(c.owner());

        uint256 balanceBefore = address(c).balance;

        c.sendMoney(target, value, data);

        uint256 balanceAfter = address(c).balance;

        // General rule: the contract's balance decreases by exactly the sent value
        assertTrue(balanceAfter == balanceBefore - value);
    }
}

